export default async function handler(req, res) {
  const {
    groupName   = 'Mi Grupo',
    inviterName = 'Alguien',
  } = req.query;

  const xe = (s) =>
    String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

  const strip = (s) =>
    s.replace(/\p{Emoji_Presentation}/gu,'').replace(/\s+/g,' ').trim();

  const raw   = strip(String(groupName)).substring(0, 32);
  const words = raw.split(' ').filter(Boolean);

  let line1 = raw, line2 = null;
  if (words.length > 1) {
    const m = Math.ceil(words.length / 2);
    line1 = words.slice(0, m).join(' ');
    line2 = words.slice(m).join(' ') || null;
  }

  const mx = Math.max(line1.length, line2 ? line2.length : 0);
  const fs = mx <= 8 ? 78 : mx <= 11 ? 70 : mx <= 14 ? 62 : mx <= 18 ? 54 : mx <= 22 ? 46 : 38;
  const lh = fs + 16;
  const y1 = line2 ? 205 : 248;
  const y2 = line2 ? y1 + lh : null;
  const yI = (y2 ?? y1) + 58;

  const BASE = "";

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630">

  <!-- Base estática -->
  <image href="data:image/png;base64,${BASE}" width="1200" height="630"/>

  <!-- Nombre del grupo -->
  <text x="450" y="${y1}"
    font-family="'Arial Black','Helvetica Neue',Arial,sans-serif"
    font-size="${fs}" font-weight="900" letter-spacing="-1.5"
    fill="#09102E" text-anchor="middle">${xe(line1)}</text>
  ${y2 ? `<text x="450" y="${y2}"
    font-family="'Arial Black','Helvetica Neue',Arial,sans-serif"
    font-size="${fs}" font-weight="900" letter-spacing="-1.5"
    fill="#09102E" text-anchor="middle">${xe(line2)}</text>` : ''}

  <!-- Invitador -->
  <text x="450" y="${yI}"
    font-family="Arial,'Helvetica Neue',sans-serif"
    font-size="28" font-weight="700"
    fill="#2C2CB0" text-anchor="middle">${xe(strip(String(inviterName)).substring(0,28))} te invit&#243; a colaborar</text>

  <!-- CTA -->
  <text x="450" y="${yI + 90}"
    font-family="'Arial Black','Helvetica Neue',Arial,sans-serif"
    font-size="38" font-weight="900"
    fill="#1C1C98" text-anchor="middle">&#218;nete a Syng</text>

</svg>`;

  res.setHeader('Content-Type', 'image/svg+xml');
  res.setHeader('Cache-Control', 'public, max-age=3600, s-maxage=3600');
  res.status(200).send(svg);
}
